// Find orders that have BOTH products and are in a modifiable state (pending)
const rows = db.prepare(\"
  SELECT o.order_id, o.customer_id, o.status, o.total_paid,
    GROUP_CONCAT(oi.name || ' (' || oi.item_id || ': ' || oi.options || ')') as items
  FROM orders o
  JOIN order_items oi ON o.order_id = oi.order_id
  WHERE o.order_id IN (
    SELECT order_id FROM order_items WHERE product_id = '7507150101'
    INTERSECT
    SELECT order_id FROM order_items WHERE product_id = '2460285426'
  )
  AND o.status = 'pending'
  GROUP BY o.order_id
\").all();
console.log('Pending orders with BOTH products:');
for (const r of rows) {
  console.log(JSON.stringify(r, null, 2));
}
"

